name: github-code
identity: "Fine-grained PAT for every repository except the platform three. Its repository list excludes agent-control, agent-registry and agent-mcp."

install:
  source: github-release
  repo: github/github-mcp-server
  version: 1.12.0
  asset: github-mcp-server_Linux_x86_64.tar.gz
  sha256: f34de295acd8f1012c7f2c0e3b909d87361d0993b9489b57ee92ac72b85d7cca

run:
  entrypoint: github-mcp-server
  args:
    # Four toolsets of the nine: the other tools are never registered, so they
    # are not merely ungranted.
    - stdio
    - --toolsets=context,repos,pull_requests,issues
    # Refuses content from repositories this token cannot write, which is the
    # direct answer to "read a public repo, obey what it says".
    - --lockdown-mode

  env:
    GITHUB_PERSONAL_ACCESS_TOKEN: secret:github_token_code

arg_denies:
  # Layer two of spec.md §4.4. The PAT's repository list is
  # layer one.
  - tools: all
    arg: owner/repo
    values:
      - example-owner/agent-control
      - example-owner/agent-registry
      - example-owner/agent-mcp
  # `main` may carry no branch protection, so the write verbs are fenced off it
  # here. `create_branch`'s `from_branch` is deliberately not fenced, because
  # branching FROM main is the point.
  - tools:
      - push_files
      - create_or_update_file
      - delete_file
      - create_branch
      - update_pull_request_branch
    arg: branch
    values: [main, master]

tools:
  - { name: get_file_contents, description: Read one file at a ref., write: false }
  - { name: list_branches, description: List a repository's branches., write: false }
  - { name: list_commits, description: List commits on a ref., write: false }
  - { name: get_commit, description: Read one commit., write: false }
  - { name: list_tags, description: List a repository's tags., write: false }
  - { name: get_latest_release, description: Read the newest release., write: false }
  - { name: get_label, description: Read one label., write: false }
  - { name: search_code, description: Search code across visible repositories., write: false }
  - { name: search_commits, description: Search commits., write: false }
  - { name: search_repositories, description: Search repositories., write: false }
  - { name: search_pull_requests, description: Search pull requests., write: false }
  - { name: pull_request_read, description: Read a pull request and its diff., write: false }
  - { name: list_pull_requests, description: List pull requests., write: false }
  - { name: create_branch, description: Create a branch from another branch., write: true }
  - { name: push_files, description: Push several files in one commit., write: true }
  - { name: create_or_update_file, description: Write one file., write: true }
  - { name: delete_file, description: Delete one file., write: true }
  - { name: create_pull_request, description: Open a pull request., write: true }
  - { name: update_pull_request, description: Change a pull request's fields., write: true }
  - { name: update_pull_request_branch, description: Update a pull request's branch., write: true }
  - { name: merge_pull_request, description: Merge a pull request., write: true }
  - { name: pull_request_review_write, description: Submit a pull request review., write: true }
  - { name: add_comment_to_pending_review, description: Add a comment to a pending review., write: true }
  - { name: add_reply_to_pull_request_comment, description: Reply to a review comment., write: true }
  - { name: add_issue_comment, description: Comment on an issue., write: true }

